export const PATTERNS_S2B: Pattern[] = [
  { id: 's2_mientras', title: 'Mientras…: ระหว่างที่', formula: 'ระหว่างที่ + A + B', rule: 'ระหว่าง ya lo conoces: «entre», «durante». Con ที่ detrás abre una frase entera: lo que pasa de fondo (A) mientras ocurre lo demás (B). Ningún verbo cambia.', examples: ['m4s14'], mark: ['ระหว่าง', 'ที่'], trap: 'Delante de un nombre va solo (ระหว่างทาง, por el camino); delante de una frase con verbo necesita ที่.' },
  { id: 's2_thii_que', title: 'El que…: ที่', formula: 'nombre + ที่ + lo que hace', rule: 'ที่ une un nombre con lo que se dice de él, como «que» en «el hombre que lleva la camisa blanca». Nunca cambia: vale para personas, cosas y lugares.', examples: ['m5s13', 'm4s22', 'm4s10'], mark: ['ที่'] },
  { id: 's2_aunque', title: 'Aunque…: ถึงแม้ว่า… ก็…', formula: 'ถึงแม้ว่า + A + ก็ + B', rule: 'ถึงแม้ว่า abre el «aunque» y ก็ va en la segunda parte, delante del verbo: pasa B a pesar de A.', examples: ['m5s17'], mark: ['ถึงแม้ว่า', 'ก็'], trap: 'No te dejes el ก็: en thai se marcan las dos mitades de la frase.' },
  { id: 's2_jon', title: 'Hasta que, tanto que: จน', formula: 'A + จน + B', rule: 'จน une lo que pasa con su resultado o su límite: llovió hasta que se inundó la calle; juegan tanto que acaban empapados.', examples: ['m6s1', 'm6s5'], mark: ['จน'] },
];

